import torch
import torch.nn as nn

class ReCAPPortfolioManager(nn.Module):
    def __init__(self, num_features, num_assets, num_regimes):
        super().__init__()
        self.regime_gate = nn.Sequential(
            nn.Linear(num_features, 64),
            nn.ReLU(),
            nn.Linear(64, num_regimes),
            nn.Softmax(dim=-1)
        )
        self.policy_library = nn.ModuleList([
            nn.Linear(num_features, num_assets) for _ in range(num_regimes)
        ])

    def forward(self, market_features):
        gate_weights = self.regime_gate(market_features)
        policy_outputs = torch.stack([
            policy(market_features) for policy in self.policy_library
        ])
        final_weights = torch.zeros_like(policy_outputs[0])
        for i in range(len(self.policy_library)):
            final_weights += gate_weights[:, i].unsqueeze(-1) * policy_outputs[i]
        return torch.softmax(final_weights, dim=-1)
